/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `invoice_audit_trigger` AFTER UPDATE ON `invoice` FOR EACH ROW BEGIN
  INSERT INTO invoice_audit (
    inv_id,
    old_inv_company,
    new_inv_company,
    old_inv_name,
    new_inv_name,
    old_inv_amount,
    new_inv_amount,
    old_inv_vat,
    new_inv_vat,
    old_inv_total_amount,
    new_inv_total_amount,
    old_inv_date,
    new_inv_date,
    old_inv_method,
    new_inv_method,
    old_inv_account,
    new_inv_account,
    old_inv_created_date,
    new_inv_created_date,
    old_inv_update_date,
    new_inv_update_date
  )
  VALUES (
    OLD.inv_id,
    OLD.inv_company,
    NEW.inv_company,
    OLD.inv_name,
    NEW.inv_name,
    OLD.inv_amount,
    NEW.inv_amount,
    OLD.inv_vat,
    NEW.inv_vat,
    OLD.inv_total_amount,
    NEW.inv_total_amount,
    OLD.inv_date,
    NEW.inv_date,
    OLD.inv_method,
    NEW.inv_method,
    OLD.inv_account,
    NEW.inv_account,
    OLD.inv_created_date,
    NEW.inv_created_date,
    OLD.inv_update_date,
    NEW.inv_update_date
  );
END */;;
