  `old_inv_date` date DEFAULT NULL,
  `new_inv_date` date DEFAULT NULL,
  `old_inv_method` varchar(255) DEFAULT NULL,
  `new_inv_method` varchar(255) DEFAULT NULL,
  `old_inv_account` varchar(255) DEFAULT NULL,
  `new_inv_account` varchar(255) DEFAULT NULL,
  `old_inv_created_date` timestamp NULL DEFAULT NULL,
  `new_inv_created_date` timestamp NULL DEFAULT NULL,
