DROP TABLE IF EXISTS `trip_import`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `trip_import` (
  `trip_id` int NOT NULL AUTO_INCREMENT,
  `invoiced` int DEFAULT '0',
  `trip_client` varchar(100) DEFAULT NULL,
  `client` varchar(100) DEFAULT NULL,
  `trip_date` date DEFAULT NULL,
  `trip_truck` int DEFAULT NULL,
  `trip_name` varchar(145) DEFAULT NULL,
  `trip_container` varchar(45) DEFAULT NULL,
  `trip_size` varchar(100) DEFAULT NULL,
  `trip_amount` double DEFAULT NULL,
  `trip_driver_rate` double DEFAULT NULL,
  `trip_type` varchar(100) DEFAULT NULL,
  `to_number` varchar(45) DEFAULT NULL,
  `ref_number` varchar(45) DEFAULT NULL,
  `trip_driver` varchar(100) DEFAULT NULL,
  `trip_confirmed` int DEFAULT '0',
  `trip_paid` int DEFAULT '0',
  `trip_create_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`trip_id`),
  KEY `idx_trip_container` (`trip_container`),
  KEY `idx_trip_client` (`trip_client`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='TRIP	TRUCK REG	CONTAINER N0	SIZE	AMOUNT	RIVER RAT	TYPE	DRIVER';
