  IN title_holder_name VARCHAR(255),
  IN owner_id_type INT,
  IN owner_id_number VARCHAR(255),
  IN owner_country INT,
  IN owner_name VARCHAR(255),
  IN owner_control_number VARCHAR(255),
  IN owner_issue_number VARCHAR(255),
  IN owner_issue_date DATE,
  IN owner_registering_authority INT,
  IN vehicle_company INT
)
BEGIN
  INSERT INTO vehicle (
    registering_authority,
    licence_number,
    vehicle_registration_number,
    vin,
    engine_number,
    make,
    model,
    vehicle_category,
    driven,
    vehicle_description,
    tare,
    date_of_liability,
    vehicle_status,
    date_liable_for_registration,
    last_three_license_numbers,
    title_holder_id_type,
    title_holder_id_number,
    title_holder_country,
    title_holder_name,
    owner_id_type,
    owner_id_number,
    owner_country,
    owner_name,
    owner_control_number,
    owner_issue_number,
    owner_issue_date,
    owner_registering_authority,
    vehicle_company
  )
  VALUES (
    registering_authority,
    licence_number,
    vehicle_registration_number,
    vin,
    engine_number,
    make,
    model,
    vehicle_category,
    driven,
    vehicle_description,
    tare,
    date_of_liability,
    vehicle_status,
    date_liable_for_registration,
    last_three_license_numbers,
    title_holder_id_type,
    title_holder_id_number,
    title_holder_country,
    title_holder_name,
    owner_id_type,
    owner_id_number,
    owner_country,
    owner_name,
    owner_control_number,
    owner_issue_number,
    owner_issue_date,
    owner_registering_authority,
    vehicle_company
  );
END ;;
